// Test block SidePanel (Navigation): The app's main navigation on the left: sections, collapsible groups and count badges, hidden on the phone until opened.
//
// Generated by tools/blocks_from_app_blocks.py from the App Block card kit/blocks/navigation/SidePanel.md and its markup
// (kit/blocks/navigation/SidePanel.html; source af63b97ce10b), with the vocabulary in
// functional/blocks/spec.json. Do not edit: change the spec (or the App Block) and generate again.
//
// Steps (e2e):
//   When I go to {section} in the side panel
//   Then the side panel shows {section} as the current page
//   Then the side panel badge for {section} says {count}
//   When I open or close the group {name}
//   When I add a collection
//   When I toggle the side panel
//   Then the side panel is open
//   Then the side panel is closed
//   Then the side panel is in the {state} state
// States (from the card): Open, Collapsed, Phone, closed, Phone, open, Group collapsed, Count changes, Long names,
// No permission. Checked by the state step: Open, Collapsed.
import { Registry } from '../../js/registry.js';
import * as p from '../../js/primitives.js';

export const BLOCK = 'SidePanel';
export const ROUTE = '';
export const STATES = ["Open", "Collapsed", "Phone, closed", "Phone, open", "Group collapsed", "Count changes", "Long names", "No permission"];
export const DEFAULT_STATE = 'Open';
export const CHECKED_STATES = ["Open", "Collapsed"];
export const DEMO = ["kit/blocks/navigation/SidePanel.html"];
export const SELF_TEST = [
  "Then the side panel is open",
  "Then the side panel shows Home as the current page",
  "Then the side panel badge for Notes says 12",
  "Then the side panel badge for Inbox says 3",
  "When I open or close the group \"Japanese 1\"",
  "When I go to Notes in the side panel",
  "Then the side panel is in the \"Open\" state",
];

export const steps = new Registry({ block: BLOCK });

/** The SidePanel block on a page: its controls, found as a person finds them (role and name, label, text). */
export class SidePanel {
  constructor(page, baseURL = '') {
    this.page = page;
    this.baseURL = baseURL;
  }

  async panel() {
    return p.control(this.page, { css: '#sidebar', block: BLOCK });
  }

  async nav() {
    return p.control(await this.panel(), { role: 'navigation', name: 'Main', block: BLOCK });
  }

  async link(section) {
    return p.control(await this.nav(), { role: 'link', name: new RegExp(`^${p.escapeRegExp(String(section))}`), block: BLOCK });
  }

  async group(name) {
    return p.control(await this.nav(), { text: String(name), block: BLOCK });
  }

  async newCollection() {
    return p.control(await this.nav(), { role: 'button', name: 'New Collection', block: BLOCK });
  }

  async toggle() {
    return p.control(this.page, { role: 'button', name: 'Show or hide the side panel', block: BLOCK });
  }

  /** Check one of the card's states: Open, Collapsed. */
  async expectState(state) {
    const b = this;
    if (state === 'Open') {
      await p.expectAttribute(await b.panel(), 'aria-hidden', 'false');
    } else if (state === 'Collapsed') {
      await p.expectAttribute(await b.panel(), 'aria-hidden', 'true');
    } else {
      throw new Error(`SidePanel has no check for the state '${state}'; checked: ${CHECKED_STATES.join(', ')}`);
    }
  }
}

steps.step("When I go to {section} in the side panel", async (world, { section }) => {
  const b = new SidePanel(world.page, world.baseURL ?? '');
  await p.click(await b.link(section));
}, { level: 'e2e' });

steps.step("Then the side panel shows {section} as the current page", async (world, { section }) => {
  const b = new SidePanel(world.page, world.baseURL ?? '');
  await p.expectAttribute(await b.link(section), 'aria-current', 'page');
}, { level: 'e2e' });

steps.step("Then the side panel badge for {section} says {count}", async (world, { section, count }) => {
  const b = new SidePanel(world.page, world.baseURL ?? '');
  await p.expectText(await b.link(section), String(count));
}, { level: 'e2e' });

steps.step("When I open or close the group {name}", async (world, { name }) => {
  const b = new SidePanel(world.page, world.baseURL ?? '');
  await p.click(await b.group(name));
}, { level: 'e2e' });

steps.step("When I add a collection", async (world, _values) => {
  const b = new SidePanel(world.page, world.baseURL ?? '');
  await p.click(await b.newCollection());
}, { level: 'e2e' });

steps.step("When I toggle the side panel", async (world, _values) => {
  const b = new SidePanel(world.page, world.baseURL ?? '');
  await p.click(await b.toggle());
}, { level: 'e2e' });

steps.step("Then the side panel is open", async (world, _values) => {
  const b = new SidePanel(world.page, world.baseURL ?? '');
  await p.expectAttribute(await b.panel(), 'aria-hidden', 'false');
}, { level: 'e2e' });

steps.step("Then the side panel is closed", async (world, _values) => {
  const b = new SidePanel(world.page, world.baseURL ?? '');
  await p.expectAttribute(await b.panel(), 'aria-hidden', 'true');
}, { level: 'e2e' });

steps.step("Then the side panel is in the {state} state", async (world, { state }) => {
  const b = new SidePanel(world.page, world.baseURL ?? '');
  await b.expectState(state);
}, { level: 'e2e' });
